reactions.onInit:
api.ensureLinkedBonus({
    items: [item],
    bonusData: {
        id: 'rank_discipline_acc',
        name: 'Rank Discipline',
        type: 'accuracy',
        val: 1,
        rollTypes: ['attack', 'check'], 
        condition: (state, actor, data, context) => {
            const l_api = game.modules.get('lancer-automations').api;
            const currentToken = actor?.token?.object 
            if (!currentToken) return false;

            const allies = l_api.getTokensInRange(currentToken, { range: 1, disposition: 'friendly' });
            // verify mech status
            return allies.some(ally => {
                if (!ally.actor) return false;

                const docType = ally.actor.type;
                return ['mech', 'npc'].includes(docType);
            });
        }
    },
    addOptions: {
        duration: 'constant' 
    }
});

api.ensureLinkedBonus({
    items: [item],
    bonusData: {
        id: `siege_armor_${item.id}`,
        name: "Siege Armor",
        type: "immunity",
        subtype: "resistance",
        damageTypes: ["all"],
        condition: (state, actor, data, context) => {
            const api = game.modules.get("lancer-automations")?.api;
            const attacker = actor.getActiveTokens()[0];
            const defender = canvas.tokens.get(context.ownerTokenId);
            return api.getTokenDistance(attacker, defender) > 3;
        }
    },
    addOptions: { 
        duration: "constant" 
    }
});

