const targets = triggerData.hitTokens
await api.executeSaveVsEffect(targets, {
    stat: "SYS",
    title: "Blind",
    origin: reactorToken,
    cardTitle: "BLIND - SYSTEMS SAVE",
    cardDescription: (target) => `<b>${target.name}</b> must pass a Systems save or be <b>Blinded</b>.`,
    effects: ["blinded"], duration: {label: 'end', turns: 1}

});

const target = triggerData.hitTokens[0];

const weapons = api.getWeapons(target).filter(weapon => !weapon.system?.tags?.some(tag => (tag.id ?? tag.lid) === 'tg_superheavy'));
if (!weapons.length)
    return ui.notifications.info(`Predatory Logic: ${target.name} has no non-Superheavy weapon.`);

const weapon = await api.pickCard(weapons, {
    title: "PREDATORY LOGIC",
    description: `Choose the weapon <b>${target.name}</b> attacks with.`,
    entryIcon: (entry) => entry.img
});
if (!weapon)
    return;

await api.beginWeaponAttackFlow(weapon, {}, { predatoryLogic: true });

// doing this with await activation because executeDamageRoll doesn't seem to work with the target otherwise
api.afterFx(async () => {
    const targets = triggerData.hitTokens;
    await api.executeDamageRoll(reactorToken, targets, api.tierValue(reactorToken, [1, 2, 3]), "Heat", "Tear Down");
    await api.applyMark(reactorToken, targets, {
        effect: { name: "Tear Down", isCustom: true, icon: "systems/lancer/assets/icons/white/damage_heat.svg" },
        flagKey: "tearDownSourceId"
    });
});

const targets = api.findMarkedTokens(reactorToken, "Tear Down", { flagKey: "tearDownSourceId" });
if (!targets || targets.length === 0) return;

await api.executeDamageRoll(reactorToken, targets, "4", "Heat", "Tear Down (Delayed)");
await api.clearMarks(reactorToken, "Tear Down", { flagKey: "tearDownSourceId" });

await api.applyEffectsToTokens({
    tokens: [reactorToken],
    effectNames: ["invisible"],
    duration: { label: "end", turns: 0 }
});

await api.applyEffectsToTokens({
    tokens: triggerData.hitTokens,
    effectNames: [{ name: "Pain Transference", icon: "systems/lancer/assets/icons/white/balance.svg", isCustom: true }],
    duration: { label: "end", turns: 1, overrideTurnOriginId: reactorToken.id }
});

const allies = api.getTokensInRange(triggerData.triggeringToken, { range: 5, disposition: 'friendly' });
if (allies.length > 0) {
    await api.executeDamageRoll(reactorToken, allies, triggerData.heatChange, "Heat", "Pain Transference");
}

Detonate Grav Spikes.activationCode:
const marked = api.findMarkedTokens(reactorToken, "Grav Spike", { flagKey: "grav_spike_source" });
if (!marked.length) {
    ui.notifications.info("No Grav Spikes to detonate.");
    return;
}

const dmg = api.tierValue(reactorToken, [4, 6, 8]);

await api.executeDamageRoll(reactorToken, marked, dmg, "Explosive", "Detonate Grav Spikes", { ap: true });

await api.knockBackToken(marked, 3, { 
    triggeringToken: reactorToken, 
    title: "GRAV SPIKE PULL",
    description: "Select destination to pull the target up to 3 spaces."
});

await api.clearMarks(reactorToken, "Grav Spike", { flagKey: "grav_spike_source" });
for (const t of marked) {
    await api.removeExtraActions(t.actor, "Remove Grav Spike");
}

Remove Grav Spike.activationCode:
const gravEffect = api.findEffectsOnToken(reactorToken, "Grav Spike")[0];
const seederId = gravEffect?.flags?.['lancer-automations']?.grav_spike_source;
const seederToken = seederId ? canvas.tokens.get(seederId) : null;

await api.executeSaveVsEffect([reactorToken], {
    stat: "SYS",
    title: "Remove Grav Spike",
    origin: seederToken,
    onPass: async (target) => {
        await api.deleteEffect(reactorToken, gravEffect);
        await api.removeExtraActions(reactorToken.actor, "Remove Grav Spike");
    }
});
